pub fn find_pmkid(key_data:&[u8]) -> Option<[u8; 16]> {
    for_each_rsn_kde(key_data,|data_type,payload| {
        if data_type == KDE_DATA_TYPE_PMKID && payload.len() >= 16 {
            return Some(payload[..16].try_into().unwrap());
        }
    });
    None
}
